import{_ as r,C as a,o as i,c as o,E as s,a2 as n}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"OAuth Refresh Can Succeed Before Persistence Fails","description":"","frontmatter":{"title":"OAuth Refresh Can Succeed Before Persistence Fails","date":"2026-08-19","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"What state should an OAuth client expose when the authorization server has issued refreshed credentials but local durable persistence fails afterward?","summary":"Remote refresh success and local persistence failure can both be true. A same-day MCP TypeScript SDK change separates them from one catch path and keeps the storage fault visible. That preserves evidence needed for recovery, but it does not provide rollback or distributed atomicity.","sources":["research/analysis/Q-20260819-03-oauth-refresh-split-commit.md"],"item_id":"Q-20260819-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-19-oauth-refresh-split-commit-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-19-oauth-refresh-split-commit.md","filePath":"en/engineering/2026-08-19-oauth-refresh-split-commit.md","lastUpdated":1787382334000}'),c={name:"en/engineering/2026-08-19-oauth-refresh-split-commit.md"};function l(h,e,d,p,u,m){const t=a("ArticleCover");return i(),o("div",null,[s(t,{image:"/assets/covers/daily-2026-08-19-oauth-refresh-split-commit-cover-v2.png",kicker:"Open-source Engineering · Daily Research",title:"OAuth Refresh Can Succeed Before Persistence Fails",summary:"Remote refresh success and local persistence failure can both be true. A same-day MCP TypeScript SDK change separates them from one catch path and keeps the storage fault visible. That preserves evidence needed for recovery, but it does not provide rollback or distributed atomicity.",version:"Q-20260819-03",status:"Daily Runtime V5 · 2026-08-19",languageHref:"/zh/engineering/2026-08-19-oauth-refresh-split-commit",languageLabel:"中文"}),e[0]||(e[0]=n('<h1 id="oauth-refresh-can-succeed-before-persistence-fails" tabindex="-1">OAuth Refresh Can Succeed Before Persistence Fails <a class="header-anchor" href="#oauth-refresh-can-succeed-before-persistence-fails" aria-label="Permalink to &quot;OAuth Refresh Can Succeed Before Persistence Fails&quot;">​</a></h1><p>The authorization server has returned a new access token and refresh token. The client then attempts to save them and receives “disk full.” Did authentication succeed or fail?</p><p>A single boolean answer loses the most important fact. Remote authority may have advanced while local durable state did not. Classifying that condition as an ordinary refresh failure and automatically redirecting to authorization is not only inaccurate; under some token-rotation policies it can hide a credential break that is difficult to recover.</p><p>A change merged into the MCP TypeScript SDK on 2026-08-19 corrects this boundary. Before the change, <code>refreshAuthorization</code> and <code>provider.saveTokens</code> shared a <code>catch</code> path, allowing selected exceptions to fall through to a new authorization request. After the change, only the remote refresh call remains inside the guarded refresh block. <code>saveTokens</code> runs after remote success, and its rejection propagates. A regression test obtains fresh tokens, forces persistence to fail with “disk full,” expects authentication to reject with that same error, and verifies that authorization redirect is not called.</p><p>The evidence supports a bounded reliability conclusion: <strong>when remote issuance and local persistence are separate operations, OAuth refresh is a split-commit workflow. Local failure after remote success is partial success and must remain visible.</strong></p><h2 id="the-two-operations-commit-in-different-authority-planes" tabindex="-1">The two operations commit in different authority planes <a class="header-anchor" href="#the-two-operations-commit-in-different-authority-planes" aria-label="Permalink to &quot;The two operations commit in different authority planes&quot;">​</a></h2><p>The remote exchange changes the credential state recognized by the authorization server. Local persistence determines whether the client can recover those credentials after a crash, restart or later request.</p><p>They happen in sequence but do not share an atomic commit. Once the remote call returns success, the server has completed its side of the operation. A later storage failure cannot make that remote success un-happen. If the server rotates refresh tokens, the previously stored token may no longer be usable.</p><p>The resulting state is not simply “authentication failed.” It is a mismatch between commit points: remote committed, local not durably committed. Safe recovery must begin from that state fact.</p><h2 id="the-catch-boundary-is-part-of-the-reliability-model" tabindex="-1">The catch boundary is part of the reliability model <a class="header-anchor" href="#the-catch-boundary-is-part-of-the-reliability-model" aria-label="Permalink to &quot;The catch boundary is part of the reliability model&quot;">​</a></h2><p>Exception handling often looks like implementation cleanup, but here the scope of a <code>catch</code> determines whether the system can preserve which side succeeded.</p><p>When remote exchange and local storage share one failure branch, a <code>saveTokens</code> rejection may be handled as a refresh error. The system sees only that “something failed during refresh,” rather than “new credentials exist but were not made durable.” An automatic authorization redirect can then cover the partial state with a new flow.</p><p>The same-day change preserves the semantic boundary. Refresh-request failures retain refresh-specific handling. Persistence failure propagates as persistence failure. The regression test demonstrates that the tested storage fault no longer silently becomes a redirect.</p><p>This is more than a better error string. It preserves the evidence classification needed for recovery decisions.</p><h2 id="visibility-is-a-prerequisite-for-recovery-not-recovery-itself" tabindex="-1">Visibility is a prerequisite for recovery, not recovery itself <a class="header-anchor" href="#visibility-is-a-prerequisite-for-recovery-not-recovery-itself" aria-label="Permalink to &quot;Visibility is a prerequisite for recovery, not recovery itself&quot;">​</a></h2><p>Propagating the storage error lets the caller know that remote exchange succeeded but local durability was not established. The caller can then choose a bounded retry, switch to safe storage, stop and alert an operator, or enter explicit reconciliation according to deployment policy.</p><p>Visibility does not repair the split state by itself. The current change adds no automatic persistence retry and defines no standard recovery object carrying the fresh credentials. If a token provider can partially write, the caller still needs to know whether the operation was atomic, merely accepted or durably committed.</p><p>A stronger provider contract could advertise:</p><ul><li>atomic replacement support;</li><li>whether success includes durable acknowledgement;</li><li>whether retry after failure is safe;</li><li>whether partial writes are possible;</li><li>which non-secret state evidence recovery requires.</li></ul><p>Those capabilities cannot be inferred universally from a method named <code>saveTokens</code>.</p><h2 id="error-propagation-is-not-transactionality" tabindex="-1">Error propagation is not transactionality <a class="header-anchor" href="#error-propagation-is-not-transactionality" aria-label="Permalink to &quot;Error propagation is not transactionality&quot;">​</a></h2><p>The evidence comes from one merged SDK change and repository tests, not an independent OAuth reliability benchmark. Server-side consequences depend on the authorization server&#39;s policy; refresh-token rotation is not universal.</p><p>The change does not create a distributed transaction between the authorization server and local storage. It cannot roll back server issuance and does not guarantee exactly-once persistence. Even if the local provider performs an atomic replace, the remote and local systems still do not share one commit protocol.</p><p>The accurate conclusion is narrower: the fault is correctly classified and remains visible, so safe recovery has the evidence it needs. Rollback, retry, coordination and operator handling still require separate design.</p><p>The remaining questions belong in interface contracts rather than operational guesswork. Should the SDK expose a structured partial-success error recording that remote issuance completed while local durability failed? How can token providers advertise atomicity, durable acknowledgement and safe-retry capability in machine-readable form? How should headless deployments alert operators before the next restart reveals that credentials were never persisted? Recovery can start from reality only when “which side committed?” is a first-class fact.</p><p><strong>Primary evidence:</strong> <a href="https://github.com/modelcontextprotocol/typescript-sdk/commit/3924de99df834302d89f5997a1b64ca268282284" target="_blank" rel="noreferrer">MCP TypeScript SDK merged commit 3924de99</a>. The code and repository tests are public primary-source evidence; they are not independent validation of distributed transactionality, rollback or universal token-rotation behavior.</p>',26))])}const b=r(c,[["render",l]]);export{y as __pageData,b as default};
